# region: sift
def sift(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
            return out
    return out

# region: emit
def emit(xs, offset=1):
    return [v + offset for v in xs]

# region: shape
def shape(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: render
def render(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return render(shape(emit(sift(raw))))

